/*
 * build-materials.js — bake data/materials.csv into js/materials-data.js.
 *
 *   ./tools/build-materials.sh
 *
 * Why a generated file exists at all: index.html is meant to open straight off
 * disk, and a file:// page cannot fetch a sibling CSV. So the CSV stays the single
 * editable source of truth and this script copies its text verbatim into a JS
 * string that materials.js parses. The generated file is committed so that
 * cloning the repo and opening index.html still works with no build step.
 */
var csv = read('data/materials.csv');

// Verify the CSV parses before writing anything, so a bad edit fails here rather
// than at page load. materials.js reads MaterialsData.csv, so stub it first.
MaterialsData = { csv: csv };
load('js/materials.js');
var list = Materials.all();

/*
 * Encode as a JS string literal. A quoted-and-escaped literal is used rather than
 * a template literal so the output stays valid ES5 like the rest of the app.
 *
 * Every non-ASCII character is escaped to \uXXXX, which makes the generated file
 * pure ASCII. That matters because the CSV comments contain em dashes: emitting
 * them raw would make the file's meaning depend on the charset the browser or the
 * jsc shell guesses, and escaping sidesteps U+2028/U+2029 line-terminator
 * pitfalls at the same time.
 */
function jsString(s) {
  var esc = s
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"')
    .replace(/\r/g, '')
    .replace(/\n/g, '\\n');

  var ascii = '';
  for (var i = 0; i < esc.length; i++) {
    var code = esc.charCodeAt(i);
    if (code < 0x20 || code > 0x7e) {
      var hex = code.toString(16);
      while (hex.length < 4) hex = '0' + hex;
      ascii += '\\u' + hex;
    } else {
      ascii += esc.charAt(i);
    }
  }
  return '"' + ascii + '"';
}

var out =
  '/*\n' +
  ' * materials-data.js -- GENERATED by tools/build-materials.sh. Do not edit.\n' +
  ' *\n' +
  ' * Edit data/materials.csv and rerun the script. This file exists only so that\n' +
  ' * index.html works when opened directly off disk, where a page cannot fetch a\n' +
  ' * local CSV. materials.js parses the string below.\n' +
  ' */\n' +
  'var MaterialsData = { csv: ' + jsString(csv) + ' };\n';

writeFile('js/materials-data.js', out);

print('js/materials-data.js written — ' + list.length + ' materials:');
list.forEach(function (m) {
  print('  ' + m.key + '  ' + m.name + ' (' + m.condition + ')  E=' +
        m.youngs_modulus_gpa + ' GPa  yield=' + m.yield_strength_mpa + ' MPa');
});
